targets.expr:
topk(10,
  sum by(query) (
    sum by(queryid) (
      rate(pg_stat_statements_calls_total{datname!~"template.*"}[$__rate_interval])
    )
    * on(queryid) group_left(query)
    pg_stat_statements_query_id{
      query=~".*($tables).*", 
      query!~".*(CREATE TABLE|REVOKE|GRANT|pg_catalog|information_schema|pg_stat).*"
    }
  )
)

histogram_quantile(0.5,
  sum by(le, uri, method, status) (
    rate(http_server_requests_seconds_bucket{instance="$instance", exception="none", uri!~".*(prometheus|health|metrics).*"}[$__rate_interval])
  )
)

topk(10,
  sum(
    sum by(queryid, datname) (
      rate(pg_stat_statements_seconds_total{datname!~"template.*|postgres"}[$__rate_interval])
    )
    * on(queryid) group_left(query)
      pg_stat_statements_query_id{
      query=~".*($tables).*", 
      query!~".*(CREATE TABLE|REVOKE|GRANT|pg_catalog|information_schema|pg_stat).*"
    }
  ) by(query)
)

topk(10,
sum(
    (
      sum by(queryid, datname) (
        rate(pg_stat_statements_seconds_total{datname!~"template.*"}[$__rate_interval])
      )
      /
      sum by(queryid, datname) (
        rate(pg_stat_statements_calls_total{datname!~"template.*"}[$__rate_interval])
      )
    )
    * on(queryid) group_left(query)
      pg_stat_statements_query_id{
      query=~".*($tables).*", 
      query!~".*(CREATE TABLE|REVOKE|GRANT|pg_catalog|information_schema|pg_stat).*"
    }
  ) by(query)
)
